<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS)
const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
  <main class="cp-ops" :data-page="pageKey" data-testid="shopping-store-operation-page">
    <header class="cp-opbar"><button type="button" @click="emit('back')"><i class="fas fa-arrow-left"></i></button><strong>coupang</strong><nav><button type="button" data-testid="shopping-open-service" @click="emit('open-service')"><i class="fas fa-headset"></i></button><button type="button" @click="emit('open-orders')"><i class="fas fa-receipt"></i></button><button type="button" @click="emit('open-cart')"><i class="fas fa-cart-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></nav></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="cp-cart">
      <div class="cp-checkout-progress"><span class="active">1 <b>{{ l('确认商品','Review') }}</b></span><i></i><span>2 <b>{{ l('配送确认','Delivery') }}</b></span><i></i><span>3 <b>{{ l('创建订单','Order') }}</b></span></div>
      <section class="cp-arrival"><i class="fas fa-bolt"></i><div><small>ROCKET / SEOUL</small><strong>{{ l('配送资格将在结算确认','Delivery eligibility is confirmed at review') }}</strong></div><span>{{ cartQuantity }} ITEMS</span></section>
      <div v-if="cartItems.length===0" class="cp-empty"><i class="fas fa-cart-shopping"></i><h1>{{ l('购物车还是空的','Your cart is empty') }}</h1><button type="button" @click="emit('back')">{{ l('返回搜索','Back to search') }}</button></div>
      <section v-else class="cp-cart-body"><div class="cp-lines"><article v-for="line in cartItems" :key="line.productId"><span class="cp-thumb"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>ROCKET</em></span><div><small>{{ serviceLabel }}</small><strong>{{ productDisplayTitle(line.product) }}</strong><b>{{ formatOrderItemSubtotal({ ...line, unitPriceCents: line.product.priceCents, currency: line.currency }) }}</b><div class="cp-qty"><button type="button" @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button type="button" @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></div><aside><p>ORDER SUMMARY</p><dl><div><dt>{{ l('商品数量','Items') }}</dt><dd>{{ cartQuantity }}</dd></div><div><dt>{{ l('配送','Delivery') }}</dt><dd>{{ l('结算时确认','At review') }}</dd></div><div><dt>{{ l('合计','Total') }}</dt><dd>{{ cartTotalLabel }}</dd></div></dl><label class="cp-gift"><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" />{{ l('作为礼物发送','Send as a gift') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">{{ l('手动填写收件人','Manual recipient') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" :placeholder="l('收件人姓名','Recipient name')" @input="emit('update:giftRecipientName',$event.target.value)" /><button type="button" data-testid="shopping-checkout" @click="emit('checkout')">{{ l('继续确认订单','Continue to review') }}</button></aside></section>
    </section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="cp-orders"><header><div><p>MY COUPANG / ORDERS</p><h1>{{ l('订单与配送','Orders & delivery') }}</h1></div><button type="button" @click="emit('open-logistics')">TRACKING →</button></header><div v-if="orders.length===0" class="cp-empty"><i class="fas fa-box-open"></i><h2>{{ l('暂无订单','No orders yet') }}</h2></div><div v-else class="cp-order-list"><article v-for="order in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="cp-order-date"><span>{{ formatLogisticsDate(order.createdAt) }}</span><b>{{ orderStatusLabel(order.status) }}</b></div><div class="cp-order-items"><i class="fas fa-box"></i><div><strong>{{ order.items.map(item=>item.title).join(' / ') }}</strong><span>{{ order.itemCount }} ITEMS · {{ formatOrderTotal(order) }}</span></div></div><footer><button type="button" :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">{{ l('查看详情','Details') }}</button><button type="button" @click="emit('delete-order',order.id)">{{ l('删除记录','Delete') }}</button></footer></article></div></section>
    <section v-else-if="pageKey==='logistics'" class="cp-tracking" data-testid="shopping-logistics-panel"><header><button type="button" @click="emit('open-orders')">← ORDERS</button><div><p>ROCKET TRACKING</p><h1>{{ l('配送路线','Delivery trace') }}</h1></div><span>{{ logisticsRows.length }}</span></header><div v-if="logisticsRows.length===0" class="cp-empty"><i class="fas fa-route"></i><h2>{{ l('暂无物流记录','No tracking records') }}</h2></div><div v-else class="cp-track-list"><article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="cp-track-line"><span class="done"><i class="fas fa-check"></i></span><i></i><span :class="{done:row.latestEvent}"><i class="fas fa-truck-fast"></i></span><i></i><span><i class="fas fa-house"></i></span></div><div><small>{{ row.latestEvent?logisticsEventTypeLabel(row.latestEvent.type):l('订单已创建','Order placed') }}</small><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><b :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</b><em v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ [row.latestEvent.carrierName,row.latestEvent.trackingCode,row.latestEvent.locationHint].filter(Boolean).join(' · ') }}</em><button type="button" :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">{{ l('查看订单','View order') }}</button></div></article></div></section>
    <section v-else-if="selectedOrder" class="cp-detail" data-testid="shopping-order-detail-panel"><header><button type="button" data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><p>ORDER DETAIL</p><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="cp-detail-summary"><div><span>{{ l('订单合计','Total') }}</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><div><span>{{ l('商品','Items') }}</span><strong>{{ selectedOrder.itemCount }}</strong></div></section><div class="cp-detail-items"><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><i class="fas fa-box"></i><div><strong>{{ item.title }}</strong><span>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item, quantity:1 }) }}</span></div><b>{{ formatOrderItemSubtotal(item) }}</b></article></div><section class="cp-timeline" data-testid="shopping-order-detail-timeline"><h2>{{ l('配送时间线','Delivery timeline') }}</h2><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><span></span><div><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary||event.title }}</p><time>{{ formatLogisticsDate(event.createdAt) }}</time></div></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">{{ l('暂无已记录的物流事件','No recorded delivery events') }}</p></section><div class="cp-detail-actions"><button type="button" data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">{{ l('确认完成','Mark completed') }}</button><button type="button" data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">{{ l('取消订单','Cancel order') }}</button><button type="button" data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">{{ l('删除记录','Delete') }}</button></div></section>
  </main>
</template>
